#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] public static class GangPresentationRepair {
 static GangPresentationRepair(){EditorApplication.update+=Request;}
 static void Request(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||!File.Exists("Temp/GangPresentation-request"))return;var cmd=File.ReadAllText("Temp/GangPresentation-request").Trim();File.Delete("Temp/GangPresentation-request");try{if(cmd=="inspect")Inspect();else if(cmd=="hands")Hands();else Apply();}catch(Exception e){File.WriteAllText("Logs/GangPresentation-result.txt",e.ToString());}}
 static Scene Scene(string path){var s=SceneManager.GetSceneByPath(path);if(!s.isLoaded)s=EditorSceneManager.OpenScene(path,OpenSceneMode.Additive);return s;}
 static void Inspect(){var s=Scene(BankPrologueBuilder.ScenePath);var d=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<BankPrologue>(true)).Single();var a=d.officers[2].animator;var hand=a.GetBoneTransform(HumanBodyBones.RightHand);var log=new StringBuilder();foreach(var t in hand.GetComponentsInChildren<Transform>(true))log.AppendLine(t.name+" parent="+(t.parent?t.parent.name:"")+" local="+t.localPosition+" rot="+t.localEulerAngles+" world="+t.position.ToString("F5")+" localExact="+t.localPosition.ToString("F6")+" axes="+t.right.ToString("F4")+"/"+t.up.ToString("F4")+"/"+t.forward.ToString("F4"));foreach(HumanBodyBones b in Enum.GetValues(typeof(HumanBodyBones)))if(b!=HumanBodyBones.LastBone&&b.ToString().StartsWith("Right")){var t=a.GetBoneTransform(b);log.AppendLine(b+" = "+(t?t.name:"NULL"));}foreach(var skin in a.GetComponentsInChildren<SkinnedMeshRenderer>()){log.AppendLine("SKIN "+skin.name+" bones "+string.Join(",",skin.bones.Select(b=>b?b.name:"null")));for(int i=0;i<skin.bones.Length;i++)if(skin.bones[i]&&skin.bones[i].name.Contains("Finger")){int ix=i;log.AppendLine("bone "+skin.bones[i].name+" same="+(skin.bones[i]==hand.Find("Finger.R"))+" weights="+skin.sharedMesh.boneWeights.Count(w=>w.boneIndex0==ix||w.boneIndex1==ix||w.boneIndex2==ix||w.boneIndex3==ix));}}File.WriteAllText("Logs/GangPresentation-rig.txt",log.ToString());}
 static void Apply(){
  int labels=0,weapons=0;var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Prologue/Art/WorldText.mat");
  foreach(var path in new[]{BankPrologueBuilder.ScenePath,StoryTutorialBuilder.Main}){
   var scene=Scene(path);EditorSceneManager.SaveScene(scene,"Logs/GangPresentation-"+scene.name+"-before-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);
   if(path==BankPrologueBuilder.ScenePath)foreach(var text in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<TextMesh>(true))){var depth=text.GetComponent<PrologueDepthText>()??text.gameObject.AddComponent<PrologueDepthText>();depth.depthMaterial=mat;text.GetComponent<Renderer>().sharedMaterial=mat;EditorUtility.SetDirty(depth);labels++;}
   else foreach(var enemy in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CitizenCombat>(true)).Where(e=>e.missionEnemy)){
    enemy.usesFirearm=false;var gun=enemy.GetComponent<GangFirearm>();if(!gun)continue;if(gun.gun)UnityEngine.Object.DestroyImmediate(gun.gun.gameObject);UnityEngine.Object.DestroyImmediate(gun);weapons++;
   }
   EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
  }
  AssetDatabase.SaveAssets();VerifyDepth(mat);File.WriteAllText("Logs/GangPresentation-result.txt","PASS saved depth-tested labels: "+labels+"; removed unintended mission firearms: "+weapons+"; front/back wall occlusion render passed");
 }
 static void Hands(){var scene=Scene(BankPrologueBuilder.ScenePath);EditorSceneManager.SaveScene(scene,"Logs/GangHands-before-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);var d=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<BankPrologue>(true)).Single();int i=0;foreach(var officer in d.officers)SyntyStoryUpgrade.Skin(officer.transform,"Assets/Synty/PolygonCity/Prefabs/Characters/Character_BusinessMan_Shirt.prefab","RecoveryGripGang"+(++i),false,true,true);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Logs/GangPresentation-result.txt","PASS articulated hands saved: "+i);}
 static void VerifyDepth(Material mat){
  var root=new GameObject("Temporary wall text depth check");root.transform.position=new Vector3(900,900,900);
  var label=new GameObject("Depth test text");label.layer=31;label.transform.SetParent(root.transform,false);var text=label.AddComponent<TextMesh>();text.text="벽 가림 TEST";text.font=AssetDatabase.LoadAssetAtPath<Font>("Assets/Fonts/BMJUA_ttf.ttf");text.fontSize=64;text.characterSize=.15f;text.anchor=TextAnchor.MiddleCenter;text.color=Color.white;label.GetComponent<Renderer>().sharedMaterial=mat;text.font.RequestCharactersInTexture(text.text,64);var depth=label.AddComponent<PrologueDepthText>();depth.depthMaterial=mat;
  var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.layer=31;wall.transform.SetParent(root.transform,false);wall.transform.localPosition=new Vector3(0,0,.2f);wall.transform.localScale=new Vector3(5,3,.1f);var black=new Material(Shader.Find("Universal Render Pipeline/Unlit"));black.SetColor("_BaseColor",Color.black);wall.GetComponent<Renderer>().sharedMaterial=black;
  var cameraObject=new GameObject("Text test camera");cameraObject.transform.SetParent(root.transform,false);var camera=cameraObject.AddComponent<Camera>();camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.nearClipPlane=.05f;camera.farClipPlane=10;var rt=new RenderTexture(256,256,24);camera.targetTexture=rt;var old=RenderTexture.active;var pixels=new Texture2D(256,256,TextureFormat.RGB24,false);
  try{var counts=new int[2];for(int i=0;i<2;i++){camera.transform.localPosition=new Vector3(0,0,i==0?-3:3);camera.transform.LookAt(label.transform.position);camera.Render();RenderTexture.active=rt;pixels.ReadPixels(new Rect(0,0,256,256),0,0);pixels.Apply();counts[i]=pixels.GetPixels().Count(c=>c.r>.5f&&c.g>.5f&&c.b>.5f);File.WriteAllBytes("Logs/GangPresentation-text-"+(i==0?"front":"back")+".png",pixels.EncodeToPNG());}File.WriteAllText("Logs/GangPresentation-text-check.txt","Front bright pixels="+counts[0]+"; behind wall="+counts[1]);if(counts[0]<10||counts[1]>2)throw new Exception("Wall text occlusion render failed");}
  finally{camera.targetTexture=null;RenderTexture.active=old;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(pixels);UnityEngine.Object.DestroyImmediate(black);UnityEngine.Object.DestroyImmediate(root);}
 }
}}
#endif


